// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;

    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(uint256 seed) public {
        // airDrop's supportsToken modifier requires msg.sender to be a contract
        // whose supportsToken() returns the expected hash, and hasNoBalance
        // requires a zero balance; a fresh eligible helper satisfies both.
        TokenSupporter actor = new TokenSupporter();
        vm.prank(address(actor));
        bool ok;
        try c.airDrop() { ok = true; } catch { ok = false; }
        vm.assume(ok);
        // Rule: after any successful airDrop, the lock is always released.
        assertTrue(!c._locked());
    }
}

contract TokenSupporter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
